"""Courses landing page: shared foundation, independent paths and searchable cards."""
import html
from portal import COURSES

def render(lang):
    z=lambda x:x[lang]
    e=lambda x:html.escape(str(x),quote=True)
    href=lambda x:x if x.startswith('https://') else '../'+x
    status=lambda c:{'ready':['已发布','Published'],'building':['建设中','In progress'],'planned':['规划中','Planned']}[c['status']][lang]
    nodes=[];cards=[]
    for c in COURSES:
        target=href(c['entry'][lang]);published=c['status']!='planned'
        link=f'<a href="{e(target)}">' if published else '<div>'
        close='</a>' if published else '</div>'
        title_link=link if published else '<span>'
        title_close=close if published else '</span>'
        nodes.append(f'''<article class="path-node" data-path-course="{e(c['id'])}">{link}<span class="path-node-kicker">{e(c['id']).upper()} · {status(c)}</span><h3>{e(z(c['subtitle']))}</h3><p>{e(z(c['outcomes']))}</p><span data-map-progress="{e(c['id'])}">{z(['原站保存进度','Progress on original site']) if c['external'] else z(['本站分项学习记录','Detailed progress on this site'])}</span>{close}</article>''')
        outline=''.join(f'<li><a href="{e(href(unit["entry"][lang]))}">{e(z(unit["title"]))}'+(' ↗' if c['external'] else '')+'</a></li>' for unit in c.get('outline',[]))
        progress=f'<div class="catalog-progress" data-catalog-progress="{e(c["id"])}"><p>{z(["正在读取本站记录…","Loading local progress…"])}</p></div>' if not c['external'] else f'<p class="catalog-progress-note">{z(["学习记录保存在作者原站。","Learning records stay on the author’s website."])}</p>'
        cards.append(f'''<article class="hub-course catalog-card" data-directory-course="{e(c['id'])}"><div class="hub-card-top"><span class="eyebrow">{e(c['id']).upper()} / {c['units']} {z(['学习单元','UNITS'])}</span><div class="catalog-badges"><span class="hub-badge status-{e(c['status'])}">{status(c)}</span><span class="hub-badge">{z(['作者原站 ↗','Author-hosted ↗']) if c['external'] else z(['本站课程','On this site'])}</span></div></div><h3>{title_link}{e(c['title'])}{title_close}</h3><p class="hub-course-subtitle">{e(z(c['subtitle']))}</p><p class="hub-course-description">{e(z(c['description']))}</p><div class="hub-tags">{''.join('<span>'+e(topic)+'</span>' for topic in c['topics'])}</div><p class="catalog-outcome"><strong>{z(['你将学会','You will learn'])}</strong> {e(z(c['outcomes']))}</p><p class="hub-course-prereq">{z(['先修','Prerequisites'])} · {e(z(c['prerequisites']))}</p><p class="catalog-meta">{z(['入门 → 进阶','Introductory → advanced'])} · 中文 / English</p>{progress}<details class="catalog-outline"><summary>{z(['查看课程大纲','View course outline'])} · {len(c.get('outline',[]))}</summary><ol>{outline}</ol></details><div class="hub-card-bottom"><span>{e(c['author'])}</span>{f'<a class="btn primary" data-course-cta="{e(c["id"])}" href="{e(target)}">'+z(['进入课程','Open course'])+(' ↗' if c['external'] else ' →')+'</a>' if published else '<span>'+z(['敬请期待','Coming soon'])+'</span>'}</div></article>''')
    return f'''<section class="wrap catalog-heading"><p class="eyebrow">COURSES / LEARNING EDA</p><h1>{z(['找到你的学习路线','Find your learning path'])}</h1><p class="lead">{z(['从共同基础出发，按问题选择课程。查看学习目标、展开大纲，再在实验与代码中检验理解。','Start with common foundations and choose a course by your goal. Explore outcomes and outlines, then test your understanding through experiments and code.'])}</p><div class="catalog-heading-bottom"><p>{len(COURSES)} {z(['门课程','courses'])} · {sum(c['status']=='ready' for c in COURSES)} {z(['门已发布','published'])} · 中文 / English</p><a href="#directory">{z(['浏览全部课程','Browse all courses'])} ↓</a></div><aside class="catalog-resume" data-catalog-resume hidden></aside></section>
<section class="intro-band catalog-map" id="map"><div class="wrap"><div class="section-head"><div><p class="eyebrow">01 / LEARNING MAP</p><h2>{z(['同一个起点，不同的视角','One foundation. Different perspectives.'])}</h2></div><p>{z(['连线表示建议的学习起点。Clustering 与 Partitioning 可独立学习，不要求先完成另一门。','Connections suggest a starting point. Clustering and Partitioning can be studied independently; neither requires completing the other.'])}</p></div><a class="path-foundation" href="../foundations/index.html"><span>START / {z(['推荐基础','RECOMMENDED FOUNDATION'])}</span><strong>{z(['节点、边权、割代价与面积','Vertices, edge weights, cut cost and area'])}</strong><span>{z(['打开基础速查','Open foundations'])} →</span></a><div class="path-branches">{''.join(nodes)}</div><p class="catalog-map-note">{z(['未开始与已完成都只是学习记录，不会限制课程访问。','Progress never locks access to a course.'])}</p></div></section>
<section class="section catalog-directory" id="directory"><div class="wrap"><div class="section-head"><div><p class="eyebrow">02 / COURSE DIRECTORY</p><h2>{z(['选择课程，开始动手','Choose a course. Start doing.'])}</h2></div><p>{z(['搜索课程、方法或课时，例如 KL、谱二分、亲和度。本站与原站入口均保留作者署名。','Search courses, methods or lessons, such as KL, spectral or affinity. Both local and external courses retain their author credits.'])}</p></div><form class="catalog-filters" data-catalog-filters role="search"><label class="catalog-query">{z(['搜索课程与课时','Search courses and lessons'])}<input name="q" type="search" placeholder="{z(['KL、谱二分、亲和度…','KL, spectral, affinity…'])}" autocomplete="off"></label><label>{z(['学习方向','Track'])}<select name="track"><option value="">{z(['全部','All'])}</option>{''.join('<option value="'+e(c['id'])+'">'+e(z(c['subtitle']))+'</option>' for c in COURSES)}</select></label><label>{z(['接入方式','Location'])}<select name="delivery"><option value="">{z(['全部','All'])}</option><option value="local">{z(['本站','On this site'])}</option><option value="external">{z(['作者原站','Author-hosted'])}</option></select></label><label>{z(['课程状态','Status'])}<select name="status"><option value="">{z(['全部','All'])}</option><option value="ready">{z(['已发布','Published'])}</option><option value="building">{z(['建设中','In progress'])}</option><option value="planned">{z(['规划中','Planned'])}</option></select></label><label>{z(['语言','Language'])}<select name="language"><option value="">{z(['全部','All'])}</option><option value="zh">中文</option><option value="en">English</option></select></label><button type="reset" class="btn quiet">{z(['重置','Reset'])}</button></form><p class="catalog-results" data-catalog-result role="status" aria-live="polite">{z(['显示全部课程','Showing all courses'])}</p><div class="catalog-lesson-results" data-lesson-results hidden></div><div class="hub-course-grid">{''.join(cards)}</div><div class="catalog-empty" data-catalog-empty hidden><h3>{z(['没有匹配的课程','No matching courses'])}</h3><p>{z(['换一个关键词，或重置筛选条件。','Try another keyword, or reset the filters.'])}</p><button class="btn quiet" data-clear-filters>{z(['清空筛选','Clear filters'])}</button></div><p class="hub-external-note">{z(['本站仅汇总本站的阅读、实验、挑战和 Python 完成记录；作者原站的进度独立保存。','Only local reading, labs, challenges and Python completion are summarized here. Author-hosted progress is stored separately.'])}</p><noscript><p>{z(['JavaScript 未启用；课程入口和大纲仍可使用，搜索筛选与进度展示需要 JavaScript。','JavaScript is disabled. Course links and outlines remain available; search, filters and progress need JavaScript.'])}</p></noscript></div></section>'''
